// Compute next attempt and exponential delay with jitter.
// Only retries on network errors (no statusCode), 408, 429 and 5xx. Other 4xx are permanent: go straight to DLQ.
const cfg = $('Config').first().json;
const res = $input.first().json;
const status = res.statusCode;
const retryable = status === undefined || status === 408 || status === 429 || status >= 500;
// $runIndex counts how many times this node has run in this execution (0-based), so it is the attempt counter.
const nextAttempt = $runIndex + 1;
const exhausted = !retryable || nextAttempt >= cfg.max_attempts;
const jitter = Math.random() * 0.25 * cfg.base_delay_seconds;
const delay = Math.min(cfg.base_delay_seconds * Math.pow(2, nextAttempt - 1) + jitter, 300);
return [{ json: {
  attempt: nextAttempt,
  exhausted,
  delay_seconds: Math.round(delay * 100) / 100,
  last_status: status ?? null,
  last_error: res.error ? String(res.error.message || res.error) : null,
  reason: retryable ? 'max_attempts_reached' : 'non_retryable_status'
} }];
